+// controlsKeyword is one leading scenario keyword that the shaper may have copied into a scenario field.
+var controlsKeyword = regexp.MustCompile(`^(?:Scenario Outline|Scenario Template|Scenario):\s+`)
+
+// controlsResolve is the plain name and the scenario indices that a scenario field designates: the
+// field as a plain name first; only when none has that name, the field with one leading keyword removed.
+// A field that designates nothing is returned as written, with no indices.
+func controlsResolve(scenarios []project.Scenario, field string) (string, []int) {
+	name := normalizeWhitespace(field)
+	if idx := controlsScenarios(scenarios, name); len(idx) > 0 {
+		return name, idx
+	}
+	if plain := controlsKeyword.ReplaceAllString(name, ""); plain != name {
+		if idx := controlsScenarios(scenarios, plain); len(idx) > 0 {
+			return plain, idx
+		}
+	}
+	return name, nil
+}
